from __future__ import annotations
import copy
import sys
sys.dont_write_bytecode = True
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
from croniter import croniter

RETENTION = timedelta(days=14)
GRACE = timedelta(minutes=15)
HUNG = timedelta(minutes=25)

def stamp(value):
    result = datetime.fromisoformat(str(value).replace('Z', '+00:00'))
    if result.tzinfo is None:
        raise ValueError('Timezone-aware timestamps required')
    return result

def slot_at(expr, now):
    return croniter(expr, now + timedelta(microseconds=1)).get_prev(datetime)

def decide(manifest, jobs, executions, state, now, artifacts, gateway_active):
    state = copy.deepcopy(state)
    if not manifest.get('activated_at') or stamp(manifest['activated_at']) > now:
        return [], state
    tz = ZoneInfo(manifest.get('timezone', 'America/Argentina/Buenos_Aires'))
    now = now.astimezone(tz)
    actions = []
    cycles = state.setdefault('cycles', {})
    live = {j['id']: j for j in jobs}
    for spec in manifest['jobs']:
        job = live.get(spec['id'])
        if not job or not job.get('enabled', True) or job.get('state') == 'paused' or job.get('paused_at'):
            continue
        slot = slot_at(spec['schedule'], now)
        if slot < stamp(manifest['activated_at']):
            continue
        key = spec['id'] + '|' + slot.isoformat()
        cycle = cycles.setdefault(key, {'slot': slot.isoformat(), 'alerts': []})
        attempts = [e for e in executions if e['job_id'] == spec['id'] and
                    stamp(e['claimed_at']) >= slot and stamp(e['claimed_at']) <= now]
        failed = [e for e in attempts if e['status'] == 'failed']
        if failed:
            if len(failed) >= 2:
                if 'failed_twice' not in cycle['alerts']:
                    actions.append({'kind': 'alert', 'code': 'failed_twice', 'job_id': spec['id'], 'cycle': key})
                    cycle['alerts'].append('failed_twice')
            elif not cycle.get('retry'):
                cycle['retry'] = {'reserved_at': now.isoformat(), 'after': failed[0]['id']}
                actions.append({'kind': 'retry', 'job_id': spec['id'], 'cycle': key,
                                'after': failed[0]['id']})
    return actions, state
